-- BUILT FILE - do not edit. Generated by tools/build.js from src/ and lib/;
-- edit those and run `npm run build`. `npm test` fails while this file is stale.

plugin = {
  id = "textdungeon-hud",
  name = "textdungeon-hud",
  version = "0.3.1",
  author = "wccrawford",
  description = "TextDungeon's Status, Effects, Slots, Page, Quest and Map as MudForge widgets, fed by the GMCP Feed.",
  settings = { saveState = true },
}

local __libs = {}
local function __require(name)
  local m = __libs[name]
  if m == nil then error("module '" .. name .. "' not found") end
  return m
end

-- lib/countdown.lua
__libs["countdown"] = (function()
  local require = __require
-- Countdown: a widget-side clock that drains toward an instant the Feed named.
-- Pure Lua 5.1 library: no globals, no clock (`now` is always an argument),
-- library-sandbox stdlib only (no Lua patterns, no string.format widths).
--
-- A Countdown is `{ ends_at = ms, span = ms }` on the caller's clock, or nil
-- when Clear. Policy (CONTEXT.md, wayfinder #7): anchor at arrival, 100 ms
-- dead-band, a Stack refills the Span, local Clear is authoritative.
local M = {}

M.DEAD_BAND_MS = 100

-- Apply a push carrying `remaining` ms (already `end - now_ms` from the Feed's
-- own clock). Returns the Countdown to keep. A push of nothing left clears.
function M.push(cd, remaining, now)
  if remaining == nil or remaining <= 0 then return nil end
  local ends_at = now + remaining
  if cd ~= nil and cd.ends_at > now then
    local delta = ends_at - cd.ends_at
    if delta >= -M.DEAD_BAND_MS and delta <= M.DEAD_BAND_MS then return cd end
    -- A Stack (lengthened) refills the bar; a shortening keeps the Span.
    local span = cd.span
    if delta > 0 then span = remaining end
    return { ends_at = ends_at, span = span }
  end
  return { ends_at = ends_at, span = remaining }
end

-- Advance the local clock: nil once the Countdown has reached Clear.
function M.tick(cd, now)
  if cd == nil or cd.ends_at <= now then return nil end
  return cd
end

-- Milliseconds left, never negative; 0 when nil.
function M.remaining(cd, now)
  if cd == nil then return 0 end
  local left = cd.ends_at - now
  if left < 0 then left = 0 end
  return left
end

-- Whole seconds, rounded up: reads `1` until the instant of Clear, never `0`.
function M.seconds(cd, now)
  return math.ceil(M.remaining(cd, now) / 1000)
end

-- Fill percentage of a draining bar (0..100, one decimal).
function M.pct(cd, now)
  if cd == nil or cd.span <= 0 then return 0 end
  local p = M.remaining(cd, now) / cd.span * 100
  if p > 100 then p = 100 end
  return math.floor(p * 10 + 0.5) / 10
end

local function pad2(n)
  if n < 10 then return "0" .. n end
  return "" .. n
end

-- Whole seconds -> "mm:ss". Negative counts as zero.
function M.mmss(seconds)
  if seconds < 0 then seconds = 0 end
  seconds = math.floor(seconds)
  local m = math.floor(seconds / 60)
  return pad2(m) .. ":" .. pad2(seconds - m * 60)
end

return M
end)()

-- lib/status.lua
__libs["status"] = (function()
  local require = __require
-- Status: the view-model behind the Status widget (Condition / Focus /
-- Footing meters, Round Time bar, Standing + Encumbrance + held power).
-- Pure Lua 5.1 library: the wiring owns a state table from `new()`, feeds it
-- Feed snapshots and the local clock, and pushes `keys()` through
-- setBoundValues. Widget states are Unfed / Live / Severed (CONTEXT.md).
local countdown = require("countdown")

local M = {}

function M.new()
  return { state = "unfed", vitals = nil, rt = nil, frozen_at = nil }
end

-- Char.Vitals snapshot: the widget goes Live on its own package's first push.
function M.vitals(s, pkg)
  if pkg == nil then return s end
  s.vitals = pkg
  s.state = "live"
  return s
end

-- Char.RoundTime snapshot: `0` or an instant already passed means clear.
function M.roundtime(s, pkg, now)
  if pkg == nil then return s end
  local remaining = 0
  if pkg.clears_at_ms ~= nil and pkg.clears_at_ms ~= 0 then
    remaining = pkg.clears_at_ms - (pkg.now_ms or 0)
  end
  s.rt = countdown.push(s.rt, remaining, now)
  return s
end

-- The local tick; returns true when the Round Time just reached Clear so the
-- caller knows the bar must be pushed one last time.
function M.tick(s, now)
  if s.state == "severed" then return false end
  local had = s.rt ~= nil
  s.rt = countdown.tick(s.rt, now)
  return had and s.rt == nil
end

-- Connection lost: keep the last-known values, freeze the Countdown here.
function M.sever(s, now)
  if s.state == "live" then
    s.state = "severed"
    s.frozen_at = now
  end
  return s
end

local function pct(cur, max)
  if cur == nil or max == nil or max <= 0 then return 0 end
  local p = cur / max * 100
  if p < 0 then p = 0 elseif p > 100 then p = 100 end
  return math.floor(p * 10 + 0.5) / 10
end

local function meter(k, key, m)
  if m == nil then
    k[key .. "Name"] = ""
    k[key .. "Cur"] = ""
    k[key .. "Max"] = ""
    k[key .. "Tier"] = ""
    k[key .. "Pct"] = "0%"
    k[key .. "Tip"] = ""
    return
  end
  k[key .. "Name"] = m.name or ""
  k[key .. "Cur"] = m.cur == nil and "" or m.cur
  k[key .. "Max"] = m.max == nil and "" or m.max
  k[key .. "Tier"] = m.tier == nil and "" or m.tier
  k[key .. "Pct"] = pct(m.cur, m.max) .. "%"
  k[key .. "Tip"] = tostring(m.cur) .. "/" .. tostring(m.max)
end

-- The complete bound-value key set for the Status widget's markup.
function M.keys(s, now)
  local k = { hudState = s.state }
  local v = s.vitals or {}
  meter(k, "cond", v.condition)
  meter(k, "focus", v.focus)
  meter(k, "foot", v.footing)
  if v.power ~= nil then
    k.powerName = v.power.name or ""
    k.powerCur = v.power.cur == nil and "" or v.power.cur
    k.powerTier = v.power.tier == nil and "" or v.power.tier
    k.powerDisplay = ""
  else
    k.powerName = ""
    k.powerCur = ""
    k.powerTier = ""
    k.powerDisplay = "none"
  end
  k.standName = v.standing and v.standing.name or ""
  k.encum = v.encumbrance == nil and "" or v.encumbrance

  if s.state == "severed" and s.frozen_at ~= nil then now = s.frozen_at end
  local cd = countdown.tick(s.rt, now)
  if cd ~= nil then
    k.rtDisplay = ""
    k.rtPct = countdown.pct(cd, now) .. "%"
    k.rtSec = countdown.seconds(cd, now)
  else
    k.rtDisplay = "none"
    k.rtPct = "0%"
    k.rtSec = ""
  end
  return k
end

return M
end)()

-- lib/effects.lua
__libs["effects"] = (function()
  local require = __require
-- Effects: the view-model behind the Effects widget (Active Effects as timer
-- rows, soonest first). Pure Lua 5.1 library, same shape as status.lua: the
-- wiring owns a state table from `new()`, feeds it Char.Effects snapshots and
-- the local clock, and pushes `keys()` through setBoundValues. Each effect
-- runs its own Countdown (CONTEXT.md); the markup is a fixed pool of POOL
-- rows flipped by bound values, never rebuilt (wayfinder #6).
local countdown = require("countdown")

local M = {}

M.POOL = 10                -- rows in the markup; beyond that only "+N more"
M.URGENT_MS = 5000         -- time and hairline turn red under this
-- A remaining past this is no deadline: the server ships a fight-bound
-- effect's end as u64::MAX (THIS_FIGHT_MS), which reaches Lua as 2^64.
-- `status` prints those "(this fight)"; so does the row.
M.FIGHT_MS = 2^53

function M.new()
  return { state = "unfed", by_name = {}, frozen_at = nil }
end

-- Char.Effects snapshot: `{ effects = { {name, ends_at_ms}, ... }, now_ms }`.
-- Walks the array with ipairs (feed arrays reach Lua 0-based under t[i]).
-- An Effect's Span is the longest remaining ever seen for its name while it
-- ran, so a re-push that lengthens it beyond the dead-band refills toward
-- that, not to the new remaining as a Round Time Stack would.
function M.effects(s, pkg, now)
  if pkg == nil then return s end
  local next_by_name = {}
  local now_ms = pkg.now_ms or 0
  for _, e in ipairs(pkg.effects or {}) do
    if e.name ~= nil and e.ends_at_ms ~= nil then
      local prev = s.by_name[e.name]
      local cd = countdown.push(prev, e.ends_at_ms - now_ms, now)
      if cd ~= nil and prev ~= nil and cd ~= prev and prev.span > cd.span then
        cd = { ends_at = cd.ends_at, span = prev.span }
      end
      if cd ~= nil then next_by_name[e.name] = cd end
    end
  end
  s.by_name = next_by_name
  s.state = "live"
  return s
end

-- The local tick; returns true when any Effect just reached Clear so the
-- caller knows its row must be pushed away.
function M.tick(s, now)
  if s.state == "severed" then return false end
  local cleared = false
  for name, cd in pairs(s.by_name) do
    if countdown.tick(cd, now) == nil then
      s.by_name[name] = nil
      cleared = true
    end
  end
  return cleared
end

-- True while any Effect is running, i.e. the tick has rows to drain.
-- (`next` is not in MudForge's sandbox; pairs is.)
function M.counting(s)
  for _ in pairs(s.by_name) do return true end
  return false
end

-- Connection lost: keep the rows, freeze every Countdown here.
function M.sever(s, now)
  if s.state == "live" then
    s.state = "severed"
    s.frozen_at = now
  end
  return s
end

-- Running Effects soonest first (name breaks ties so the order is stable).
local function sorted(s, now)
  local list = {}
  for name, cd in pairs(s.by_name) do
    if countdown.tick(cd, now) ~= nil then
      list[#list + 1] = { name = name, cd = cd }
    end
  end
  table.sort(list, function(a, b)
    if a.cd.ends_at ~= b.cd.ends_at then return a.cd.ends_at < b.cd.ends_at end
    return a.name < b.name
  end)
  return list
end

-- The complete bound-value key set for the Effects widget's markup:
-- hudState, effEmpty, effMore, and e<i>n / e<i>t / e<i>u / e<i>p / e<i>d
-- (name, mm:ss, urgency flag, hairline width, row display) for each pool row.
function M.keys(s, now)
  if s.state == "severed" and s.frozen_at ~= nil then now = s.frozen_at end
  local k = { hudState = s.state }
  local list = sorted(s, now)
  k.effEmpty = (s.state ~= "unfed" and #list == 0) and "" or "none"
  k.effMore = (#list > M.POOL) and ("+" .. (#list - M.POOL) .. " more") or ""
  for i = 1, M.POOL do
    local p = "e" .. i
    local e = list[i]
    if e ~= nil then
      local left = countdown.remaining(e.cd, now)
      local fight = left >= M.FIGHT_MS
      k[p .. "n"] = e.name
      k[p .. "t"] = fight and "this fight" or countdown.mmss(countdown.seconds(e.cd, now))
      k[p .. "u"] = (left < M.URGENT_MS) and 1 or 0
      k[p .. "p"] = fight and "100%" or (countdown.pct(e.cd, now) .. "%")
      k[p .. "d"] = ""
    else
      k[p .. "n"] = ""
      k[p .. "t"] = ""
      k[p .. "u"] = 0
      k[p .. "p"] = "0%"
      k[p .. "d"] = "none"
    end
  end
  return k
end

return M
end)()

-- lib/slots.lua
__libs["slots"] = (function()
  local require = __require
-- Slots: the view-model behind the Slots widget (every worn and held Slot
-- of the character's Race as a ledger, `label | item`, empties dimmed with
-- EMPTY for the item; bound text is ASCII only, since MudForge's Lua-to-JS
-- bridge shows a UTF-8 string's bytes as Latin-1).
-- Pure Lua 5.1 library, same shape as status.lua: the wiring owns a state
-- table from `new()`, feeds it Char.Items snapshots, and pushes `keys()`
-- through setBoundValues. No Countdown here, so no clock and no tick; the
-- markup is a fixed pool of POOL rows flipped by bound values, never rebuilt
-- (wayfinder #6). Order is the Feed's, which is the Race's (wayfinder #4).
local M = {}

M.POOL = 16                -- rows in the markup; beyond that only "+N more"
M.EMPTY = "----"           -- stands in for an empty Slot's item

function M.new()
  return { state = "unfed", slots = {} }
end

-- Char.Items snapshot: `{ slots = { {slot, instance, item|null}, ... } }`.
-- Walks the array with ipairs (feed arrays reach Lua 0-based under t[i]) and
-- keeps only what the ledger shows; `instance` is dropped. A Race with no
-- Slots is an empty list, which is still Live.
function M.items(s, pkg)
  if pkg == nil then return s end
  local list = {}
  for _, e in ipairs(pkg.slots or {}) do
    if e.slot ~= nil then
      list[#list + 1] = { label = e.slot, item = e.item }
    end
  end
  s.slots = list
  s.state = "live"
  return s
end

-- Connection lost: keep the last-known ledger, only the state changes.
function M.sever(s)
  if s.state == "live" then s.state = "severed" end
  return s
end

-- The complete bound-value key set for the Slots widget's markup:
-- hudState, slotsEmpty, slotsMore, and s<i>l / s<i>i / s<i>e / s<i>d
-- (label, item, empty flag, row display) for each pool row.
function M.keys(s)
  local k = { hudState = s.state }
  local n = #s.slots
  k.slotsEmpty = (s.state ~= "unfed" and n == 0) and "" or "none"
  k.slotsMore = (n > M.POOL) and ("+" .. (n - M.POOL) .. " more") or ""
  for i = 1, M.POOL do
    local p = "s" .. i
    local e = s.slots[i]
    if e ~= nil then
      k[p .. "l"] = e.label
      k[p .. "i"] = e.item ~= nil and e.item or M.EMPTY
      k[p .. "e"] = (e.item == nil) and 1 or 0
      k[p .. "d"] = ""
    else
      k[p .. "l"] = ""
      k[p .. "i"] = ""
      k[p .. "e"] = 1
      k[p .. "d"] = "none"
    end
  end
  return k
end

return M
end)()

-- lib/recent.lua
__libs["recent"] = (function()
  local require = __require
-- Recent: the newest-first list of the last few documents a reader widget
-- was fed, and which of them is on show (CONTEXT.md: Recent, On show).
-- Pure Lua 5.1 library shared by pages.lua and quests.lua: each entry is
-- the caller's table, found again by the `key` it was put under.
local M = {}

M.LIMIT = 10               -- entries kept; the oldest falls off the end

function M.new(limit)
  return { items = {}, at = 0, limit = limit or M.LIMIT }
end

local function indexOf(r, key)
  for i, it in ipairs(r.items) do
    if it.key == key then return i end
  end
  return nil
end

-- Where the entry under `key` stands (1 = newest), or nil.
M.find = indexOf

-- Put `entry` at the head under `key` and show it. An entry already under
-- that key is taken out first, so a document re-fed moves up, never twice.
function M.put(r, key, entry)
  local i = indexOf(r, key)
  if i ~= nil then table.remove(r.items, i) end
  table.insert(r.items, 1, { key = key, entry = entry })
  while #r.items > r.limit do table.remove(r.items) end
  r.at = 1
  return r
end

-- Replace the head's entry in place when it is under `key`; whatever is on
-- show stays on show. Answers whether it did.
function M.refresh(r, key, entry)
  local head = r.items[1]
  if head == nil or head.key ~= key then return false end
  head.entry = entry
  return true
end

-- The entry on show, or nil while Recent is empty.
function M.shown(r)
  local it = r.items[r.at]
  return it and it.entry
end

function M.count(r)
  return #r.items
end

-- Show entry `i` (1 = newest); out of range is ignored.
function M.show(r, i)
  if i ~= nil and i >= 1 and i <= #r.items then r.at = i end
  return r
end

function M.older(r) return M.show(r, r.at + 1) end
function M.newer(r) return M.show(r, r.at - 1) end

-- Every entry, newest first, as { entry, ... }.
function M.entries(r)
  local out = {}
  for i, it in ipairs(r.items) do out[i] = it.entry end
  return out
end

return M
end)()

-- lib/doc.lua
__libs["doc"] = (function()
  local require = __require
-- Doc: markup for the reader widgets (Page, Quest), whose content is
-- rewritten whole on every change rather than flipped by bound values
-- (ADR 0002). Pure Lua 5.1 library: everything here returns a string.
-- Fed text is escaped on the way in; nothing fed ever reaches markup raw.
local M = {}

-- The twelve Roles a fed Span may carry (ADR 0058's role names); any other
-- name is drawn plain rather than trusted into a class attribute.
local ROLES = {
  Item = true, Character = true, Place = true, Exit = true, Speech = true,
  Refusal = true, Harm = true, Cue = true, Warning = true, Command = true,
  Act = true, Heading = true,
}

-- Fed `lines` copied into plain tables. Feed arrays reach Lua 0-based
-- under t[i] (wayfinder #6), so every list goes through ipairs at the door.
function M.copy(lines)
  local out = {}
  for _, line in ipairs(lines or {}) do
    local spans = {}
    for _, sp in ipairs(line) do
      if type(sp) == "table" then
        spans[#spans + 1] = { text = sp.text, role = sp.role, hang = sp.hang }
      end
    end
    out[#out + 1] = spans
  end
  return out
end

function M.escape(s)
  s = tostring(s or "")
  s = (s:gsub("&", "&amp;"))
  s = (s:gsub("<", "&lt;"))
  s = (s:gsub(">", "&gt;"))
  s = (s:gsub('"', "&quot;"))
  return s
end

-- A widget's own font, as getWidgetFont answers it (`{family, size, weight}`,
-- the widget's settings cog), as the three bound style keys a bound
-- widget's root carries: fontSize, fontFamily, fontWeight. Absent parts
-- are left to the stylesheet ("" clears a bound style).
function M.fontKeys(font)
  font = font or {}
  return {
    fontSize = font.size ~= nil and (tostring(font.size) .. "px") or "",
    fontFamily = font.family or "",
    fontWeight = font.weight ~= nil and tostring(font.weight) or "",
  }
end

-- The same font as an inline style attribute, for a widget whose markup
-- is rewritten whole; "" when there is none.
function M.fontStyle(font)
  local k = M.fontKeys(font)
  local out = {}
  if k.fontSize ~= "" then out[#out + 1] = "font-size:" .. k.fontSize end
  if k.fontFamily ~= "" then out[#out + 1] = "font-family:" .. k.fontFamily end
  if k.fontWeight ~= "" then out[#out + 1] = "font-weight:" .. k.fontWeight end
  if #out == 0 then return "" end
  return ' style="' .. M.escape(table.concat(out, ";")) .. '"'
end

-- One fed line, a list of Spans `{text, role?}` or hangs `{hang = n}`: its
-- words as role-classed spans, wrapped continuations starting at the last
-- hang's column (ADR 0058: a line with none hangs at 0).
function M.line(spans)
  local out, hang = {}, 0
  for _, sp in ipairs(spans or {}) do
    if type(sp) == "table" then
      if sp.hang ~= nil then
        hang = tonumber(sp.hang) or 0
      elseif sp.text ~= nil and sp.text ~= "" then
        local text = M.escape(sp.text)
        if sp.role ~= nil and ROLES[sp.role] then
          out[#out + 1] = '<span class="r-' .. sp.role .. '">' .. text .. "</span>"
        else
          out[#out + 1] = text
        end
      end
    end
  end
  local style = ""
  if hang > 0 then
    style = ' style="padding-left:' .. hang .. "ch;text-indent:-" .. hang .. 'ch"'
  end
  return '<div class="ln"' .. style .. ">" .. table.concat(out) .. "</div>"
end

-- Every fed line, in order.
function M.lines(lines)
  local out = {}
  for _, l in ipairs(lines or {}) do out[#out + 1] = M.line(l) end
  return table.concat(out)
end

-- A clickable control: `data-mud-action` fires the widget's `action` event
-- (MudForge); a control that cannot act now is drawn dimmed with no action.
function M.button(label, action, data, on, enabled, extra)
  local cls = "btn" .. (on and " on" or "") .. (extra and (" " .. extra) or "")
  if enabled == false then
    return '<span class="' .. cls .. ' off">' .. label .. "</span>"
  end
  local d = data ~= nil and (' data-mud-data="' .. M.escape(data) .. '"') or ""
  return '<span class="' .. cls .. '" data-mud-action="' .. action .. '"' .. d .. ">" .. label .. "</span>"
end

-- The reader frame: widget state for the shared dimming, a navigation bar
-- over Recent, then the body.
--   v = { state, at, count, listing, label, tools?, body, foot?, font? }
-- `at`/`count` place the shown entry in Recent (1 = newest); `listing` is
-- true while the Recent list is the body; `tools` is markup for the
-- widget's own buttons, set just before Recent; `foot` markup for a bar
-- under the body; `font` the widget's own (see fontStyle).
function M.frame(v)
  local bar = {
    M.button("&lsaquo;", "older", nil, false, v.at < v.count, "nav"),
    M.button("&rsaquo;", "newer", nil, false, v.at > 1, "nav"),
    '<span class="pos">' .. (v.count > 0 and (v.at .. "/" .. v.count) or "") .. "</span>",
    '<span class="lbl">' .. (v.label or "") .. "</span>",
    v.tools or "",
    M.button("Recent", "recent", nil, v.listing, v.count > 0),
  }
  return '<div class="hud rd" data-state="' .. v.state .. '"' .. M.fontStyle(v.font) .. ">"
    .. '<div class="bar">' .. table.concat(bar) .. "</div>"
    .. '<div class="body">' .. (v.body or "") .. "</div>"
    .. (v.foot and ('<div class="bar foot">' .. v.foot .. "</div>") or "")
    .. "</div>"
end

-- The Recent list as a body: one row per entry, newest first, the shown
-- one marked; a row opens its entry. rows = { {label, sub?}, ... }
function M.recent(rows, at)
  local out = {}
  for i, row in ipairs(rows) do
    local sub = row.sub and ('<span class="sub">' .. row.sub .. "</span>") or ""
    out[#out + 1] = '<div class="row' .. (i == at and " cur" or "") .. '" data-mud-action="open" data-mud-data="' .. i .. '">'
      .. '<span class="rl">' .. row.label .. "</span>" .. sub .. "</div>"
  end
  return table.concat(out)
end

-- The body of a widget with nothing to show yet.
function M.empty(text)
  return '<div class="none">' .. M.escape(text) .. "</div>"
end

return M
end)()

-- lib/pages.lua
__libs["pages"] = (function()
  local require = __require
-- Pages: the view-model behind the Page widget - what `read` last printed
-- (Writing.Read, a page or a table of contents), kept in Recent so the
-- player can page back through what they read this connection, and turned
-- on the side band (Page.Read) without the prose scrolling past them.
-- Pure Lua 5.1 library, same shape as slots.lua (new / feed / sever) plus
-- act() for the widget's clicks and html() for its whole content (ADR 0002).
local recent = require("recent")
local doc = require("doc")

local M = {}

function M.new()
  return { state = "unfed", recent = recent.new(), listing = false }
end

local function copyRows(pages)
  local out = {}
  for _, r in ipairs(pages or {}) do
    if r.page ~= nil then
      out[#out + 1] = { page = r.page, title = r.title or "", section = r.section, rung = r.rung }
    end
  end
  return out
end

-- Writing.Read: `{kind = "page", writing, page, title, lines}` or
-- `{kind = "contents", writing, pages}`. It answers a `read` the player just
-- typed, so it always goes on show, even over an older entry being browsed.
function M.read(s, pkg)
  if pkg == nil or pkg.writing == nil then return s end
  local e
  if pkg.kind == "contents" then
    e = { kind = "contents", writing = pkg.writing, rows = copyRows(pkg.pages) }
    recent.put(s.recent, pkg.writing .. "#contents", e)
  elseif pkg.kind == "page" then
    e = { kind = "page", writing = pkg.writing, page = pkg.page, title = pkg.title or "", lines = doc.copy(pkg.lines) }
    recent.put(s.recent, pkg.writing .. "#" .. tostring(pkg.page), e)
  else
    return s
  end
  s.listing = false
  s.refusal = nil
  s.state = "live"
  return s
end

-- Page.Refused `{writing, page?, text}`: a Page.Read the server would not
-- answer, with the words `read` would have printed. Shown over whatever is
-- on show, which stays, until the next click or page read.
function M.refused(s, pkg)
  if pkg == nil or pkg.text == nil then return s end
  s.refusal = tostring(pkg.text)
  return s
end

-- A Page.Read request for the wiring to send: page `n` of `writing`, or its
-- contents when `n` is nil.
local function ask(writing, n)
  return { gmcp = "Page.Read", data = { writing = writing, page = n } }
end

-- The page a turn from page entry `e` reaches, `step` -1 or +1, or nil.
-- With the book's contents in Recent it is the nearest page they list that
-- way; without, the next number, never below 1.
local function turnTo(r, e, step)
  local n = tonumber(e.page)
  if n == nil then return nil end
  local i = recent.find(r, e.writing .. "#contents")
  if i == nil then
    if n + step < 1 then return nil end
    return n + step
  end
  local best = nil
  for _, row in ipairs(recent.entries(r)[i].rows) do
    local p = tonumber(row.page)
    if p ~= nil and (p - n) * step > 0 and (best == nil or (p - best) * step < 0) then best = p end
  end
  return best
end

-- Connection lost: Recent is kept, only the state changes.
function M.sever(s)
  if s.state == "live" then s.state = "severed" end
  return s
end

-- A click in the widget (its `data-mud-action` / `data-mud-data`). Answers
-- the Page.Read request to send, if the click asks for one: a contents row
-- reads its page, a turn reads the page it names, and Contents on a page
-- reads its book's contents unless they are already in Recent, which it
-- shows instead.
function M.act(s, action, data)
  local r = s.recent
  s.refusal = nil
  if action == "older" then recent.older(r); s.listing = false
  elseif action == "newer" then recent.newer(r); s.listing = false
  elseif action == "recent" then s.listing = not s.listing and recent.count(r) > 0
  elseif action == "open" then recent.show(r, tonumber(data)); s.listing = false
  elseif action == "read" then
    local e = recent.shown(r)
    local n = tonumber(data)
    if e ~= nil and e.kind == "contents" and n ~= nil then
      return ask(e.writing, n)
    end
  elseif action == "turn" then
    local e = recent.shown(r)
    local n = tonumber(data)
    if e ~= nil and e.kind == "page" and not s.listing and n ~= nil then
      return ask(e.writing, n)
    end
  elseif action == "contents" then
    local e = recent.shown(r)
    if e ~= nil and e.kind == "page" then
      local i = recent.find(r, e.writing .. "#contents")
      if i == nil then return ask(e.writing, nil) end
      recent.show(r, i)
      s.listing = false
    end
  end
  return nil
end

local function label(e)
  if e.kind == "contents" then return doc.escape(e.writing) .. " - contents" end
  return doc.escape(e.writing) .. " - p. " .. doc.escape(e.page)
end

-- `read <book>`'s contents, as read prints them: section headings, then
-- each page row clickable to read it, its rung in brackets.
local function contents(e)
  local out = { '<div class="ln"><span class="r-Heading">' .. doc.escape(e.writing) .. "</span></div>" }
  local heading = nil
  for _, row in ipairs(e.rows) do
    if row.section ~= nil and row.section ~= heading then
      heading = row.section
      out[#out + 1] = '<div class="ln sec"><span class="r-Heading">' .. doc.escape(heading) .. "</span></div>"
    end
    local rung = row.rung ~= nil and ('  <span class="sub">(' .. doc.escape(row.rung) .. ")</span>") or ""
    out[#out + 1] = '<div class="row" data-mud-action="read" data-mud-data="' .. doc.escape(row.page) .. '">'
      .. '<span class="pn">' .. doc.escape(row.page) .. ".</span>"
      .. '<span class="rl">' .. doc.escape(row.title) .. rung .. "</span></div>"
  end
  return table.concat(out)
end

-- A page's foot: turn back on the left, on on the right, each to the page
-- it names; a way with no page is left out.
local function foot(r, e)
  local back, on = turnTo(r, e, -1), turnTo(r, e, 1)
  return (back and doc.button("&lsaquo; p. " .. back, "turn", back) or "")
    .. '<span class="gap"></span>'
    .. (on and doc.button("p. " .. on .. " &rsaquo;", "turn", on) or "")
end

-- The widget's whole content, in `font` (the widget's own, see doc.fontStyle).
function M.html(s, font)
  local r = s.recent
  local n = recent.count(r)
  local e = recent.shown(r)
  local v = { state = s.state, at = r.at, count = n, listing = s.listing, font = font }
  if e == nil then
    v.body = doc.empty("Nothing read yet.")
  elseif s.listing then
    local rows = {}
    for i, it in ipairs(recent.entries(r)) do
      rows[i] = { label = label(it), sub = it.kind == "page" and doc.escape(it.title) or nil }
    end
    v.label = "Recent pages"
    v.body = doc.recent(rows, r.at)
  else
    v.label = label(e)
    v.body = e.kind == "contents" and contents(e) or doc.lines(e.lines)
    if e.kind == "page" then
      v.tools = doc.button("Contents", "contents")
      v.foot = foot(r, e)
    end
  end
  if s.refusal ~= nil then
    v.body = '<div class="note r-Refusal">' .. doc.escape(s.refusal) .. "</div>" .. v.body
  end
  return doc.frame(v)
end

return M
end)()

-- lib/quests.lua
__libs["quests"] = (function()
  local require = __require
-- Quests: the view-model behind the Quest widget - the last quest the
-- player pulled up (Quest.Show, kept current by the server), with the ones
-- pulled up before it kept in Recent as they last stood.
-- Pure Lua 5.1 library, same shape as pages.lua (ADR 0002).
local recent = require("recent")
local doc = require("doc")

local M = {}

function M.new()
  return { state = "unfed", recent = recent.new(), listing = false }
end

-- Quest.Show `{title, status, lines}`. The server re-sends it unasked as the
-- quest moves (and on a resync): the same quest at the head is refreshed in
-- place and whatever the player is browsing stays on show. A different
-- quest was just pulled up, so it goes on show.
function M.show(s, pkg)
  if pkg == nil or pkg.title == nil then return s end
  local e = { title = pkg.title, status = pkg.status or "", lines = doc.copy(pkg.lines) }
  if not recent.refresh(s.recent, pkg.title, e) then
    recent.put(s.recent, pkg.title, e)
    s.listing = false
  end
  s.state = "live"
  return s
end

function M.sever(s)
  if s.state == "live" then s.state = "severed" end
  return s
end

-- A click in the widget; never asks the MUD for anything.
function M.act(s, action, data)
  local r = s.recent
  if action == "older" then recent.older(r); s.listing = false
  elseif action == "newer" then recent.newer(r); s.listing = false
  elseif action == "recent" then s.listing = not s.listing and recent.count(r) > 0
  elseif action == "open" then recent.show(r, tonumber(data)); s.listing = false
  end
  return nil
end

-- A status word as a class: `in progress` -> `st-in-progress`.
local function status(e)
  local cls = (e.status:gsub("[^%w]+", "-"))
  return '<span class="st st-' .. cls .. '">' .. doc.escape(e.status) .. "</span>"
end

-- The widget's whole content, in `font` (the widget's own, see doc.fontStyle).
function M.html(s, font)
  local r = s.recent
  local n = recent.count(r)
  local e = recent.shown(r)
  local v = { state = s.state, at = r.at, count = n, listing = s.listing, font = font }
  if e == nil then
    v.body = doc.empty("No quest pulled up yet.")
  elseif s.listing then
    local rows = {}
    for i, it in ipairs(recent.entries(r)) do
      rows[i] = { label = doc.escape(it.title), sub = status(it) }
    end
    v.label = "Recent quests"
    v.body = doc.recent(rows, r.at)
  else
    v.label = status(e)
    v.body = doc.lines(e.lines)
    -- Only the head is kept current by the server; an older one is a snapshot.
    if r.at > 1 then
      v.body = v.body .. '<div class="note">As last shown. Type <span class="r-Command">quests show</span> to bring it up to date.</div>'
    end
  end
  return doc.frame(v)
end

return M
end)()

-- lib/bar.lua
__libs["bar"] = (function()
  local require = __require
-- Bar: the view-model behind the Windows bar - one button per HUD window,
-- each opening its window. MudForge has no way yet to bring back a custom
-- window the player closed, so this bar is how they do it, and the wiring
-- shows the bar itself on every start (ADR 0002 for the markup). It only
-- opens: MudForge tells a plugin nothing when a window is closed from its
-- own chrome, so a toggle could not know which way to go.
-- Pure Lua 5.1 library: act() answers which window a click opens.
local doc = require("doc")

local M = {}

-- windows = { {name, title}, ... } in bar order.
function M.new(windows)
  local s = { windows = {} }
  for i, w in ipairs(windows) do
    s.windows[i] = { name = w.name, title = w.title }
  end
  return s
end

-- A click: `open` on a window the bar holds answers its name.
function M.act(s, action, data)
  if action ~= "open" then return nil end
  for _, w in ipairs(s.windows) do
    if w.name == data then return w.name end
  end
  return nil
end

-- The bar's whole content, in `font` (the widget's own, see doc.fontStyle).
function M.html(s, font)
  local out = {}
  for _, w in ipairs(s.windows) do
    out[#out + 1] = doc.button(doc.escape(w.title), "open", w.name)
  end
  return '<div class="wbar"' .. doc.fontStyle(font) .. ">" .. table.concat(out) .. "</div>"
end

return M
end)()

-- lib/map.lua
__libs["map"] = (function()
  local require = __require
-- Map: the view-model behind the Map window - the Plane of the Area the
-- player stands in (GMCP Area.Map), where they and their Group are on it
-- (Area.Where), and the one level being drawn. Terms are CONTEXT.md's
-- (Plane, Held position, Level shown, Browsing, No-plane reason).
-- Pure Lua 5.1 library, same shape as pages.lua (new / feed / sever, act()
-- for the widget's clicks, html() for its whole content, ADR 0002). The
-- drawing is look A, "Tiles" (wayfinder #23), framed by Fit (#22), with the
-- level bar under the plane (#24). It draws only what the package says.
local doc = require("doc")

local M = {}

function M.new()
  return { state = "unfed", members = {} }
end

-- Any Feed snapshot on this connection: a window with no Area.Map yet can
-- then say why it has no Plane.
function M.live(s)
  if s.state == "unfed" then s.state = "live" end
  return s
end

local function list(t)
  local out = {}
  for _, w in ipairs(t or {}) do out[#out + 1] = tostring(w) end
  return out
end

-- One room of the package, copied: only the keys the drawing reads, the
-- objects walked with pairs and the arrays with ipairs (feed arrays reach
-- Lua 0-based under t[i]). A room with no whole cell is left off the Plane.
local function copyRoom(r)
  local x, y, z = tonumber(r.x), tonumber(r.y), tonumber(r.z)
  if x == nil or y == nil or z == nil then return nil end
  local out = { x = x, y = y, z = z, exits = {}, doors = {},
    leaves = list(r.leaves), unexplored = list(r.unexplored) }
  if type(r.terrain) == "string" then out.terrain = r.terrain end
  if r.back ~= nil then out.back = tostring(r.back) end
  for w, id in pairs(r.exits or {}) do out.exits[tostring(w)] = tostring(id) end
  for w, d in pairs(r.doors or {}) do
    if type(d) == "table" then
      out.doors[tostring(w)] = { name = tostring(d.name or w), closed = d.closed == true }
    end
  end
  return out
end

-- Area.Where's members as room id -> sorted names, keeping only those whose
-- room is on the Plane.
local function group(rooms, members)
  local out = {}
  for name, id in pairs(members or {}) do
    id = tostring(id)
    if rooms[id] ~= nil then
      out[id] = out[id] or {}
      table.insert(out[id], tostring(name))
    end
  end
  for _, names in pairs(out) do table.sort(names) end
  return out
end

-- MudForge's sandbox has no `next`, so emptiness is asked of pairs.
local function empty(t)
  for _ in pairs(t) do return false end
  return true
end

local function levels(rooms)
  local seen, zs = {}, {}
  for _, r in pairs(rooms or {}) do
    if not seen[r.z] then seen[r.z] = true; zs[#zs + 1] = r.z end
  end
  table.sort(zs)
  return zs, seen
end

local function hasLevel(rooms, z)
  for _, r in pairs(rooms) do
    if r.z == z then return true end
  end
  return false
end

-- The level shown when not Browsing: the player's, else 0, else the lowest.
local function baseLevel(s)
  if s.here ~= nil then return s.rooms[s.here].z end
  local zs, seen = levels(s.rooms)
  if seen[0] then return 0 end
  return zs[1]
end

-- Moves the markers to a position whose room is on the Plane. A new `here`
-- ends Browsing; a member moving does not.
local function place(s, here, members)
  if here ~= s.here then s.browse = nil end
  s.here = here
  s.members = group(s.rooms, members)
  s.off = false
  s.held = nil
end

-- Area.Map: a new Plane, replacing the old whole. A Plane for another Area
-- drops the markers until Area.Where places them and ends Browsing; a
-- re-send of the same Area keeps both where they still fit. A Held position
-- whose room the new Plane holds is applied.
function M.map(s, pkg)
  if pkg == nil then return s end
  local rooms = {}
  for id, r in pairs(pkg.rooms or {}) do
    if type(r) == "table" then rooms[tostring(id)] = copyRoom(r) end
  end
  local area = tostring(pkg.area or "")
  local same = s.rooms ~= nil and s.area == area
  s.area = area
  s.region = pkg.region ~= nil and tostring(pkg.region) or nil
  local holds = pkg.holds or {}
  s.holds = { enemies = list(holds.enemies), gather = list(holds.gather) }
  s.rooms = rooms
  s.state = "live"
  if same then
    if s.here ~= nil and rooms[s.here] == nil then s.here = nil end
    for id in pairs(s.members) do
      if rooms[id] == nil then s.members[id] = nil end
    end
    if s.browse ~= nil and not hasLevel(rooms, s.browse) then s.browse = nil end
  else
    s.here = nil
    s.members = {}
    s.browse = nil
    s.off = false
  end
  if s.held ~= nil and rooms[s.held.here] ~= nil then
    place(s, s.held.here, s.held.members)
  end
  return s
end

-- Area.Where: the player and their Group. With no `here` the player is off
-- the Plane. A `here` not on the Plane yet is held (only the newest) and
-- moves nothing until a Plane that holds it arrives.
function M.where(s, pkg)
  if pkg == nil then return s end
  s.state = "live"
  if pkg.here == nil then
    s.off = true
    s.held = nil
    return s
  end
  local here = tostring(pkg.here)
  if s.rooms ~= nil and s.rooms[here] ~= nil then
    place(s, here, pkg.members)
  else
    s.held = { here = here, members = pkg.members }
  end
  return s
end

-- Connection lost: the Plane and the markers stay, frozen.
function M.sever(s)
  if s.state == "live" then s.state = "severed" end
  return s
end

-- The Level shown, or nil with no Plane to show.
function M.shown(s)
  if s.rooms == nil or empty(s.rooms) then return nil end
  if s.browse ~= nil then return s.browse end
  return baseLevel(s)
end

function M.browsing(s)
  return s.browse ~= nil
end

-- A click in the widget. `level` with `z<n>` shows level z = n, or with
-- `mine` the player's. The z rides with a letter because MudForge drops a
-- click's data when it reads as a falsy number, which "0" would; asking for the level shown by default is not
-- Browsing. Nothing is ever sent to the server.
function M.act(s, action, data)
  if action ~= "level" or s.rooms == nil then return nil end
  if data == "mine" then
    s.browse = nil
    return nil
  end
  local z = tonumber(type(data) == "string" and data:match("^z(%-?%d+)$") or nil)
  if z == nil or not hasLevel(s.rooms, z) then return nil end
  if z == baseLevel(s) then s.browse = nil else s.browse = z end
  return nil
end

-- ===== Drawing: look A, "Tiles" =====

local U = 20      -- one cell in SVG units; Fit scales the viewBox, so this is only proportion
local T = 12      -- a tile
local HT = T / 2
local EDGE = 2.6
local PAD = 18    -- room around the Plane's bounds for stubs and marks
local CAP = 34    -- the largest a cell is drawn, in px

local DIRS = {
  north = { 0, 1 }, south = { 0, -1 }, east = { 1, 0 }, west = { -1, 0 },
  northeast = { 1, 1 }, northwest = { -1, 1 }, southeast = { 1, -1 }, southwest = { -1, -1 },
}

local TERRAIN = {
  inside = "#7d8590", city = "#a371f7", road = "#c2a878", field = "#6cae4f", forest = "#2e8b57",
  water = "#3b82c4", swamp = "#808c2e", cave = "#9a6b4f", hills = "#d29b45",
}
local NONE = "#3d444d"
local YOU, GROUP, BACK, LINE, DOOR, DARK = "#ffd33d", "#ff7b72", "#39c5cf", "#8b949e", "#f0883e", "#0d1117"

-- Tile-local textures: every tile is drawn inside its own translate(), so a
-- userSpaceOnUse pattern starts at the tile's corner and lines up from tile
-- to tile. The tile is 12 units and each pattern 6.
local INK = 'stroke="#000" stroke-opacity=".38"'
local INKF = 'fill="#000" fill-opacity=".38"'
local PAT = {
  city = '<path d="M0 .5h6M0 3.5h6M1.5 .5v3M4.5 3.5v3" fill="none" ' .. INK .. ' stroke-width=".8"/>',
  road = '<path d="M.5 3h2.4M3.5 3h2" fill="none" ' .. INK .. ' stroke-width="1.1"/>',
  field = '<circle cx="3" cy="3" r=".95" ' .. INKF .. "/>",
  forest = '<path d="M3 .8l2.2 3.8H.8z" ' .. INKF .. "/>",
  water = '<path d="M0 3q1.5-2 3 0t3 0" fill="none" stroke="#fff" stroke-opacity=".45" stroke-width=".9"/>',
  swamp = '<path d="M0 4.5q1.5-1.5 3 0t3 0M1.5 .8v2M4.5 1.2v1.6" fill="none" ' .. INK .. ' stroke-width=".85"/>',
  cave = '<path d="M1 2.2h1.6M3.6 4.6h1.6M.4 5.4h.8M4.2 1h1" fill="none" ' .. INK .. ' stroke-width="1.3" stroke-linecap="round"/>',
  hills = '<path d="M.3 4.8q2.7-4.2 5.4 0" fill="none" ' .. INK .. ' stroke-width=".9"/>',
}
local PAT_ORDER = { "city", "road", "field", "forest", "water", "swamp", "cave", "hills" }
-- inside has no texture: a room in a room
local INSIDE = '<rect x="2.5" y="2.5" width="7" height="7" rx="1" fill="none" ' .. INK .. ' stroke-width="1.1"/>'

-- A number for markup: at most two decimals, no trailing zeros, no "-0".
local function n(v)
  local s
  if v % 1 == 0 then s = string.format("%d", v)
  else s = (string.format("%.2f", v):gsub("0+$", ""):gsub("%.$", "")) end
  if s == "-0" then s = "0" end
  return s
end

local function px(r) return r.x * U end
local function py(r) return -r.y * U end   -- north is +y; SVG y grows down

local function off(w, d)
  local v = DIRS[w]
  return v[1] * d, -v[2] * d
end

local function sign(v)
  if v > 0 then return 1 elseif v < 0 then return -1 end
  return 0
end

local function sortedIds(rooms)
  local ids = {}
  for id in pairs(rooms) do ids[#ids + 1] = id end
  table.sort(ids)
  return ids
end

local function sortedKeys(t)
  local ks = {}
  for k in pairs(t) do ks[#ks + 1] = k end
  table.sort(ks)
  return ks
end

-- The first character of a name (UTF-8), for a Group marker.
local function initial(name)
  return name:match("^[%z\1-\127\194-\244][\128-\191]*") or "?"
end

-- Everything the level shown needs, worked out once: its rooms with their
-- marks, the edges between them (each pair once), and the stubs.
local function scene(s)
  local z = M.shown(s)
  local rooms, edges, stubs, seen = {}, {}, {}, {}
  for _, id in ipairs(sortedIds(s.rooms)) do
    local r = s.rooms[id]
    if r.z == z then
      local o = { id = id, r = r, odd = {} }
      for _, w in ipairs(sortedKeys(r.exits)) do
        local tid = r.exits[w]
        local t = s.rooms[tid]
        if t ~= nil then
          if t.z ~= r.z then
            if t.z > r.z then o.up = true else o.down = true end
          else
            local k = id < tid and (id .. "|" .. tid) or (tid .. "|" .. id)
            local door = r.doors[w]
            if seen[k] then
              if door ~= nil and seen[k].door == nil then seen[k].door = door end
            else
              seen[k] = { a = r, b = t, word = w, door = door,
                far = math.max(math.abs(t.x - r.x), math.abs(t.y - r.y)) > 1 }
              edges[#edges + 1] = seen[k]
            end
          end
        end
      end
      for _, kind in ipairs({ "leaves", "unexplored" }) do
        for _, w in ipairs(r[kind]) do
          if w == "up" then o.up = o.up or kind
          elseif w == "down" then o.down = o.down or kind
          elseif DIRS[w] then stubs[#stubs + 1] = { r = r, word = w, kind = kind, door = r.doors[w] }
          else o.odd[#o.odd + 1] = { word = w, kind = kind } end
        end
      end
      if r.back ~= nil then
        if DIRS[r.back] then stubs[#stubs + 1] = { r = r, word = r.back, kind = "back", door = r.doors[r.back] }
        else o.odd[#o.odd + 1] = { word = r.back, kind = "back" } end
      end
      rooms[#rooms + 1] = o
    end
  end
  return { z = z, rooms = rooms, edges = edges, stubs = stubs }
end

local STAIR = { [true] = "stairs", leaves = "leaves this map", unexplored = "unexplored" }

-- A room's tooltip: its terrain, stairs, doors, and the ways that leave.
local function tip(o)
  local r = o.r
  local t = { r.terrain or "no terrain" }
  if o.up then t[#t + 1] = "up: " .. STAIR[o.up] end
  if o.down then t[#t + 1] = "down: " .. STAIR[o.down] end
  for _, w in ipairs(sortedKeys(r.doors)) do
    t[#t + 1] = w .. ": " .. r.doors[w].name .. (r.doors[w].closed and " (closed)" or " (open)")
  end
  for _, w in ipairs(r.leaves) do
    if w ~= "up" and w ~= "down" then t[#t + 1] = w .. " leaves this map" end
  end
  for _, w in ipairs(r.unexplored) do
    if w ~= "up" and w ~= "down" then t[#t + 1] = w .. ": unexplored" end
  end
  if r.back ~= nil then t[#t + 1] = r.back .. " leads back out" end
  return table.concat(t, "\n")
end

local function line(x1, y1, x2, y2, attrs)
  return '<line x1="' .. n(x1) .. '" y1="' .. n(y1) .. '" x2="' .. n(x2) .. '" y2="' .. n(y2) .. '" ' .. attrs .. "/>"
end

local DEFS = (function()
  local out = { "<defs>" }
  for _, t in ipairs(PAT_ORDER) do
    out[#out + 1] = '<pattern id="pA-' .. t .. '" width="6" height="6" patternUnits="userSpaceOnUse">' .. PAT[t] .. "</pattern>"
  end
  for _, m in ipairs({ { "aA", LINE }, { "aB", BACK } }) do
    out[#out + 1] = '<marker id="' .. m[1] .. '" viewBox="0 0 6 6" refX="2" refY="3" markerWidth="6" markerHeight="6" markerUnits="userSpaceOnUse" orient="auto"><path d="M0 0L6 3L0 6z" fill="' .. m[2] .. '"/></marker>'
  end
  out[#out + 1] = "</defs>"
  return table.concat(out)
end)()

local SD = 'stroke="' .. DARK .. '" stroke-width="1.2" stroke-linejoin="round"'

-- An up or down mark on a tile's right corner: solid for a stair on the
-- Plane, hollow when it leaves the map, hollow and dashed when unexplored.
local function tri(cx, cy, dir, how)
  local d = "M" .. n(cx - 3.6) .. " " .. n(cy + 2.6 * dir) .. "L" .. n(cx) .. " " .. n(cy - 3 * dir)
    .. "L" .. n(cx + 3.6) .. " " .. n(cy + 2.6 * dir) .. "z"
  local title = "<title>" .. (dir == 1 and "up: " or "down: ") .. STAIR[how] .. "</title>"
  if how == true then return '<path class="stair" d="' .. d .. '" fill="#fff" ' .. SD .. ">" .. title .. "</path>" end
  return '<path class="stair" d="' .. d .. '" fill="' .. DARK .. '" stroke="#fff" stroke-width="1.2" stroke-linejoin="round"'
    .. (how == "unexplored" and ' stroke-dasharray="1.6 1"' or "") .. ">" .. title .. "</path>"
end

-- The plane as SVG: the whole Plane's x/y bounds framed by the viewBox, so
-- the frame holds still while Browsing; the cell size capped by max sizes.
local function svg(s, sc)
  local x0, x1, y0, y1 = math.huge, -math.huge, math.huge, -math.huge
  for _, r in pairs(s.rooms) do
    x0, x1 = math.min(x0, r.x), math.max(x1, r.x)
    y0, y1 = math.min(y0, r.y), math.max(y1, r.y)
  end
  local w, h = (x1 - x0) * U + 2 * PAD, (y1 - y0) * U + 2 * PAD
  local g = {}
  local function add(part) g[#g + 1] = part end

  for _, e in ipairs(sc.edges) do
    add(line(px(e.a), py(e.a), px(e.b), py(e.b), 'stroke="' .. LINE .. '" stroke-width="' .. EDGE .. '"'
      .. (e.far and ' stroke-dasharray="3 2"' or "")))
  end
  for _, st in ipairs(sc.stubs) do
    local x, y = px(st.r), py(st.r)
    local ax, ay = off(st.word, HT)
    local bx, by = off(st.word, U * 0.6)
    local col = st.kind == "back" and BACK or LINE
    local attrs = 'stroke="' .. col .. '" stroke-width="' .. EDGE .. '"'
    if st.kind == "unexplored" then attrs = attrs .. ' stroke-dasharray="2 1.6"'
    else attrs = attrs .. ' marker-end="url(#' .. (st.kind == "back" and "aB" or "aA") .. ')"' end
    add(line(x + ax, y + ay, x + bx, y + by, attrs))
    if st.kind == "unexplored" then
      local qx, qy = off(st.word, U * 0.6 + 3)
      add('<g><title>' .. doc.escape(st.word) .. ': unexplored</title><circle cx="' .. n(x + qx) .. '" cy="' .. n(y + qy)
        .. '" r="3.4" fill="' .. DARK .. '" stroke="#e6edf3" stroke-width="1"/><text x="' .. n(x + qx) .. '" y="' .. n(y + qy + 2)
        .. '" font-size="5.4" font-weight="700" text-anchor="middle" fill="#e6edf3">?</text></g>')
    end
  end

  local marks = {}
  for _, o in ipairs(sc.rooms) do
    local r = o.r
    local x, y = px(r) - HT, py(r) - HT
    add('<g class="room" transform="translate(' .. n(x) .. " " .. n(y) .. ')"><title>' .. doc.escape(tip(o)) .. "</title>"
      .. '<rect width="' .. T .. '" height="' .. T .. '" rx="2" fill="' .. (TERRAIN[r.terrain] or NONE) .. '"'
      .. (TERRAIN[r.terrain] and "" or ' stroke="#6e7681" stroke-width=".8"') .. "/>")
    if r.terrain == "inside" then add(INSIDE)
    elseif PAT[r.terrain] then add('<rect width="' .. T .. '" height="' .. T .. '" rx="2" fill="url(#pA-' .. r.terrain .. ')"/>') end
    add("</g>")
    -- marks sit on the tile's corners, half outside it, over everything else
    if o.up then marks[#marks + 1] = tri(x + T, y + 1.5, 1, o.up) end
    if o.down then marks[#marks + 1] = tri(x + T, y + T - 1.5, -1, o.down) end
    if #o.odd > 0 then
      local words, bk = {}, false
      for i, q in ipairs(o.odd) do
        words[i] = q.word
        if q.kind == "back" then bk = true end
      end
      marks[#marks + 1] = '<g class="odd"><title>' .. doc.escape(table.concat(words, ", ")) .. '</title><circle cx="' .. n(x) .. '" cy="' .. n(y)
        .. '" r="3.6" fill="' .. (bk and BACK or "#fff") .. '" ' .. SD .. '/><path d="M' .. n(x - 1.5) .. " " .. n(y + 1.5) .. "L" .. n(x + 1.6) .. " " .. n(y - 1.6)
        .. "M" .. n(x - 0.6) .. " " .. n(y - 1.6) .. "H" .. n(x + 1.6) .. "V" .. n(y + 0.6) .. '" fill="none" stroke="' .. DARK .. '" stroke-width="1"/></g>'
    end
  end

  -- doors: across the line at the cell boundary; closed a bar, open two
  -- posts. Drawn over the you ring, which would otherwise hide half a door
  -- on the player's own tile.
  local doors = {}
  local function door(a, word, b, d)
    local v = DIRS[word] or { sign(b.x - a.x), sign(b.y - a.y) }
    local mx, my = px(a) + v[1] * U / 2, py(a) - v[2] * U / 2
    local len = math.sqrt(v[1] * v[1] + v[2] * v[2])
    local nx, ny = -v[2] / len, -v[1] / len
    local L = 4.8
    local title = "<title>" .. doc.escape(d.name) .. (d.closed and " (closed)" or " (open)") .. "</title>"
    if d.closed then
      doors[#doors + 1] = '<g class="door">' .. title .. line(mx - nx * L, my - ny * L, mx + nx * L, my + ny * L, 'stroke="' .. DOOR .. '" stroke-width="3"') .. "</g>"
    else
      doors[#doors + 1] = '<g class="door" stroke="' .. DOOR .. '" stroke-width="2.2">' .. title
        .. line(mx - nx * L, my - ny * L, mx - nx * 2.2, my - ny * 2.2, "")
        .. line(mx + nx * 2.2, my + ny * 2.2, mx + nx * L, my + ny * L, "") .. "</g>"
    end
  end
  for _, e in ipairs(sc.edges) do
    if e.door ~= nil then door(e.a, e.word, e.b, e.door) end
  end
  for _, st in ipairs(sc.stubs) do
    if st.door ~= nil then door(st.r, st.word, nil, st.door) end
  end

  -- the Group: a disc with the initial on the tile's bottom-left corner,
  -- fanning right when several share a room
  for _, id in ipairs(sortedKeys(s.members)) do
    local r = s.rooms[id]
    if r.z == sc.z then
      for i, name in ipairs(s.members[id]) do
        local x, y = px(r) - HT + (i - 1) * 6, py(r) + HT
        add('<g class="member"><title>' .. doc.escape(name) .. '</title><circle cx="' .. n(x) .. '" cy="' .. n(y) .. '" r="4" fill="' .. GROUP
          .. '" stroke="' .. DARK .. '" stroke-width="1.2"/><text x="' .. n(x) .. '" y="' .. n(y + 1.9)
          .. '" font-size="5.4" text-anchor="middle" fill="' .. DARK .. '" font-weight="700">' .. doc.escape(initial(name)) .. "</text></g>")
      end
    end
  end

  -- you: a ring around the tile with a dot in its centre
  local you = s.here ~= nil and s.rooms[s.here] or nil
  if you ~= nil and you.z == sc.z then
    local with = s.members[s.here]
    local title = "You" .. (with and (", with " .. table.concat(with, ", ")) or "")
    add('<g class="you"><title>' .. doc.escape(title) .. '</title><rect x="' .. n(px(you) - HT - 2.6) .. '" y="' .. n(py(you) - HT - 2.6)
      .. '" width="' .. n(T + 5.2) .. '" height="' .. n(T + 5.2) .. '" rx="3.5" fill="none" stroke="' .. YOU .. '" stroke-width="2.4"/>'
      .. '<circle cx="' .. n(px(you)) .. '" cy="' .. n(py(you)) .. '" r="2.8" fill="' .. YOU .. '" stroke="' .. DARK .. '" stroke-width="1.2"/></g>')
  end
  for _, d in ipairs(doors) do add(d) end
  for _, m in ipairs(marks) do add(m) end   -- over the you ring, so it never hides a mark

  return '<svg class="plane" viewBox="' .. n(x0 * U - PAD) .. " " .. n(-y1 * U - PAD) .. " " .. n(w) .. " " .. n(h)
    .. '" preserveAspectRatio="xMidYMid meet" style="max-width:' .. n(w / U * CAP) .. "px;max-height:" .. n(h / U * CAP) .. 'px">'
    .. DEFS .. table.concat(g) .. "</svg>"
end

local function head(s)
  return '<div class="mhead"><span class="marea">' .. doc.escape(s.area) .. "</span>"
    .. (s.region ~= nil and ('<span class="mregion">' .. doc.escape(s.region) .. "</span>") or "") .. "</div>"
end

-- The level bar: ▼ Level n of m ▲, with whoever is on another level by the
-- arrow that leads to them (you too, while Browsing). None on a 1-level Plane.
local function levelBar(s, z)
  local zs = levels(s.rooms)
  if #zs < 2 then return "" end
  local at = 1
  for i, v in ipairs(zs) do if v == z then at = i end end
  local function nth(v)
    for i, w in ipairs(zs) do if w == v then return i end end
  end
  local function act(v) return ' data-mud-action="level" data-mud-data="' .. doc.escape(v) .. '"' end
  local function arrow(glyph, title, to)
    if to == nil then return '<span class="lvarrow off" title="' .. title .. '">' .. glyph .. "</span>" end
    return '<span class="lvarrow" title="' .. title .. '"' .. act(to) .. ">" .. glyph .. "</span>"
  end
  local who = { up = {}, down = {} }
  local you = s.here ~= nil and s.rooms[s.here] or nil
  if you ~= nil and you.z ~= z then
    table.insert(who[you.z > z and "up" or "down"], '<span class="lvyou" title="You: level ' .. nth(you.z) .. ' (back to you)"' .. act("mine") .. "></span>")
  end
  for _, id in ipairs(sortedKeys(s.members)) do
    local r = s.rooms[id]
    if r.z ~= z then
      for _, name in ipairs(s.members[id]) do
        table.insert(who[r.z > z and "up" or "down"], '<span class="lvmem" title="' .. doc.escape(name .. ": level " .. nth(r.z)) .. '"'
          .. act("z" .. n(r.z)) .. ">" .. doc.escape(initial(name)) .. "</span>")
      end
    end
  end
  return '<div class="mlevel"><span class="lvend">' .. arrow("&#9660;", "Level below", zs[at - 1] and ("z" .. n(zs[at - 1])))
    .. table.concat(who.down) .. "</span>"
    .. '<span class="lvmid' .. (s.browse ~= nil and " browsing" or "") .. '">Level ' .. at .. " of " .. #zs .. "</span>"
    .. '<span class="lvend lvr">' .. table.concat(who.up) .. arrow("&#9650;", "Level above", zs[at + 1] and ("z" .. n(zs[at + 1]))) .. "</span></div>"
end

local function holds(s)
  local out = {}
  for _, k in ipairs({ { "enemies", "Enemies" }, { "gather", "Gather" } }) do
    local names = s.holds[k[1]]
    if #names > 0 then
      local esc = {}
      for i, v in ipairs(names) do esc[i] = doc.escape(v) end
      out[#out + 1] = "<div><b>" .. k[2] .. "</b> " .. table.concat(esc, ", ") .. "</div>"
    end
  end
  if #out == 0 then return "" end
  return '<div class="mholds">' .. table.concat(out) .. "</div>"
end

local function reason(text)
  return '<div class="mreason">' .. text .. "</div>"
end

-- The widget's whole content, in `font` (the widget's own, see doc.fontStyle).
-- A No-plane reason is shown only while Live.
function M.html(s, font)
  local live = s.state == "live"
  local body
  if s.state == "unfed" or s.rooms == nil then
    body = live and reason("No map from the server yet. If <code>config map</code> is off, <code>config map on</code> brings it back.")
      or '<div class="mnone">Map</div>'
  elseif s.off then
    body = live and reason("You are not on the map of " .. doc.escape(s.area) .. ".") or '<div class="mnone">Map</div>'
  elseif empty(s.rooms) then
    body = head(s) .. (live and reason(doc.escape(s.area) .. " has no map.") or "")
  else
    local sc = scene(s)
    body = head(s) .. '<div class="mbody">' .. svg(s, sc) .. "</div>" .. levelBar(s, sc.z) .. holds(s)
  end
  return '<div class="hud mapwin" data-state="' .. s.state .. '"' .. doc.fontStyle(font) .. ">" .. body .. "</div>"
end

return M
end)()

